makeMtLab(document.getElementById("lab-l34"),{id:"l34",scenarios:[{"label": "Ví dụ: GET /machines", "note": "Trả danh sách ba máy.", "steps": [{"t": "Gửi yêu cầu", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">GET /machines<\/span><\/div>"}, {"t": "Phản hồi", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">200 [{\"machine_id\":\"L1-M1\",...},{...},{...}]<\/span><\/div>", "ask": {"q": "Danh sách có mấy phần tử?", "o": ["1", "3", "0"], "a": 1}}]}, {"label": "Ví dụ: Tham số đường dẫn", "note": "{machine_id}.", "steps": [{"t": "GET /machines/L1-M2", "html": "<p class=\"mt-calc\">machine_id = 'L1-M2'<\/p>"}, {"t": "Phản hồi", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">200 {\"machine_id\":\"L1-M2\",\"name\":\"Máy dán nắp\"}<\/span><\/div>"}]}, {"label": "Ví dụ: 404", "note": "HTTPException.", "steps": [{"t": "GET /machines/L1-M9", "html": "<p class=\"mt-calc\">Không có trong MACHINES<\/p>"}, {"t": "Phản hồi", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">404 {\"detail\":\"Không có máy L1-M9\"}<\/span><\/div>"}]}, {"label": "Lỗi: Trả None thay vì 404", "note": "Quên kiểm tra.", "steps": [{"t": "return MACHINES.get(machine_id)", "html": "<p class=\"mt-calc\">Máy không tồn tại → None<\/p>"}, {"t": "Phản hồi", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">200 null<\/span><\/div>", "say": "<p>Bên gọi tưởng thành công. Ném HTTPException 404.<\/p>"}]}, {"label": "Bẫy: Chạy fastapi dev ở xưởng", "note": "Chế độ phát triển.", "steps": [{"t": "fastapi dev trên máy chủ xưởng", "html": "<p class=\"mt-calc\">Tự nạp lại khi file đổi, hiện lỗi chi tiết<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">fastapi run sau proxy, có đăng nhập<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l34"),"l34",[{"kind": "num", "t": "API", "d": "<p>Trả lời bằng một số.<\/p>", "items": [{"q": "Cổng mặc định của fastapi dev trong bài?", "a": 8000}, {"q": "GET /machines trả bao nhiêu máy?", "a": 3, "unit": "máy"}, {"q": "Mã trạng thái khi máy không tồn tại?", "a": 404}], "hints": ["Xem dòng Serving at.", "Đếm khóa trong MACHINES."], "why": "8000; 3; 404."}, {"kind": "pick", "t": "Phần nào làm gì?", "d": "<p>Ghép phần mã với vai trò.<\/p>", "cats": ["Khai báo đường dẫn", "Tham số", "Trả lỗi"], "items": [{"q": "@app.get(\"/machines\")", "a": 0}, {"q": "machine_id: str", "a": 1}, {"q": "raise HTTPException(404)", "a": 2}, {"q": "@app.get(\"/machines/{machine_id}\")", "a": 0}], "hints": ["Trình trang trí khai báo đường dẫn.", "Tham số hàm nhận giá trị từ đường dẫn."], "why": "Trình trang trí: đường dẫn; machine_id: tham số; HTTPException: lỗi."}, {"kind": "order", "t": "Viết và thử endpoint", "d": "<p>Sắp xếp.<\/p>", "items": ["pip install fastapi[standard]", "Viết api.py với @app.get", "fastapi dev mini_mes/api.py", "Mở /docs", "Bấm thử GET /machines"], "hints": ["Cài trước.", "Thử sau khi chạy."], "why": "Cài → viết → chạy → /docs → thử."}]);
mesSim(document.getElementById("sim-l34"),Object.assign({id:"l34"},{kind:"term",title:"Chạy endpoint đầu tiên",sub:"Mô phỏng theo nội dung bài (PENDING: chạy thử trên Windows). Invoke-RestMethod là lệnh gọi HTTP của PowerShell.",cwd:"C:\\amts\\mini-mes",vars:{fa:false,up:false},
 prompt:S=>"(.venv) PS "+S.cwd+"> ",hints:["python -m pip install \"fastapi[standard]\"","fastapi dev mini_mes/api.py","Invoke-RestMethod http://127.0.0.1:8000/machines","Invoke-RestMethod http://127.0.0.1:8000/machines/L1-M1","Invoke-RestMethod http://127.0.0.1:8000/machines/L1-M9"],
 cmds:[{re:/^(python -m )?pip install "?fastapi\[standard\]"?$/i,out:"Successfully installed fastapi uvicorn … (danh sách rút gọn)",fx:(m,S)=>{S.fa=true}},
  {re:/^fastapi dev mini_mes[\\/]api\.py$/i,out:(m,S)=>S.fa?"Serving at: http://127.0.0.1:8000\nAPI docs: http://127.0.0.1:8000/docs\n(máy chủ chạy nền trong mô phỏng; trên máy thật mở cửa sổ PowerShell thứ hai để gọi thử)":{err:"fastapi : The term 'fastapi' is not recognized… (chưa cài fastapi[standard])"},fx:(m,S)=>{if(S.fa)S.up=true}},
  {re:/^(Invoke-RestMethod|irm|curl) (http:\/\/127\.0\.0\.1:8000)?(\/\S*)$/i,out:(m,S)=>{if(!S.up)return{err:"Invoke-RestMethod : Unable to connect to the remote server"};const p=m[3];
    if(p==="/machines")return"machine_id name\n---------- ----\nL1-M1      Máy rót\nL1-M2      Máy dán nắp\nL1-M3      Máy cân";
    const k=/^\/machines\/(L1-M[123])$/.exec(p);if(k)return"machine_id : "+k[1]+"\nstate      : "+(k[1]==="L1-M2"?"DOWN":"RUNNING");
    if(/^\/machines\/\S+$/.test(p))return{err:"Invoke-RestMethod : {\"detail\":\"Không có máy "+p.split("/").pop()+"\"}\n(404 Not Found: HTTPException(404) trong hàm)"};
    if(p==="/docs")return"(trang HTML Swagger UI: mở bằng trình duyệt)";return{err:"Invoke-RestMethod : {\"detail\":\"Not Found\"}"}}}],
 tasks:[{t:"Cài fastapi[standard] và chạy <code>fastapi dev mini_mes/api.py</code>.",check:s=>s.S.up},
  {t:"Gọi danh sách máy và trạng thái L1-M1.",check:s=>s.ran(/\/machines$/)&&s.ran(/\/machines\/L1-M1$/)},
  {t:"Gọi máy L1-M9 không có.",ok:"Hàm raise HTTPException(404): FastAPI trả JSON {\"detail\": …} với mã 404.",check:(s,c)=>c.has("cmd",e=>/L1-M9/.test(e.line)&&/404/.test(e.out))}]}));

